shell-n3-safe-divide:
def safe_divide(a, b):
    if b == 0:
        return "erro: divisao por zero"
    return a / b

variables-n1-build-username:
def build_username(first, last):
    full = first + last
    return full.lower()

variables-n3-price-total:
def price_total(price_str, quantity_str):
    price = float(price_str)
    quantity = int(quantity_str)
    total = price * quantity
    return round(total, 2)

loops-for-n1-sum-to-n:
def sum_to_n(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

loops-for-n2-count-passed:
def count_passed(scores):
    passed = 0
    for score in scores:
        if score >= 70:
            passed += 1
    return passed

loops-for-n2-build-csv:
def build_csv(items):
    result = ""
    for item in items:
        result += str(item) + ","
    return result.rstrip(",")

loops-for-n3-build-test-ids:
def build_test_ids(prefix, count):
    ids = []
    for i in range(1, count + 1):
        ids.append(prefix + "-" + str(i).zfill(3))
    return ids

