def classify_age(age):
    if age < 13:
        return "crianca"
    elif age < 18:
        return "adolescente"
    else:
        return "adulto"

ifstmt-n3-grade-letter:
def grade_letter(score):
    if score < 0 or score > 100:
        return "invalido"
    elif score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    elif score >= 60:
        return "D"
    else:
        return "F"

lists-n2-sum-even-indexes:
def sum_at_even_indexes(numbers):
    total = 0
    for i in range(len(numbers)):
        if i % 2 == 0:
            total += numbers[i]
    return total

lists-n2-first-negative:
def first_negative_index(numbers):
    for i in range(len(numbers)):
        if numbers[i] < 0:
            return i
    return -1

lists-n3-clean-scores:
def clean_scores(scores):
    cleaned = []
    for s in scores:
        if s is not None:
            cleaned.append(s)
    cleaned.sort()
    return cleaned

nested-loops-n1-count-cells:
def count_cells(grid):
    total = 0
    for row in grid:
        for cell in row:
            total += 1
    return total

nested-loops-n2-count-matches:
def count_matches(grid, target):
    count = 0
    for row in grid:
        for cell in row:
            if cell == target:
                count += 1
    return count

nested-loops-n3-validate-grid:
def validate_grid(grid):
    errors = []
    if not grid:
        return errors
    width = len(grid[0])
    for r, row in enumerate(grid):
        if len(row) != width:
            errors.append(f"linha {r} tem {len(row)} colunas, esperado {width}")
        for c, cell in enumerate(row):
            if not isinstance(cell, int):
                errors.append(f"celula ({r}, {c}) nao e inteiro")
    return errors

functions-n2-greet-fullname:
def full_name(first, last):
    return first + " " + last

def greet(first, last):
    return "Olá, " + full_name(first, last) + "!"

functions-n3-apply-discount:
def apply_discount(price, percent):
    if percent < 0 or percent > 100:
        return None
    discount = price * percent / 100
    return round(price - discount, 2)

