dictionaries-n2-count-status:
def count_status(statuses):
    counts = {}
    for s in statuses:
        if s in counts:
            counts[s] += 1
        else:
            counts[s] = 1
    return counts

dictionaries-n3-merge-config:
def merge_test_config(defaults, overrides):
    result = {}
    for k in defaults:
        result[k] = defaults[k]
    for k in overrides:
        result[k] = overrides[k]
    return result
